const s=document.querySelector(".lheader"),r=()=>s.classList.toggle("is-scrolled",window.scrollY>8);window.addEventListener("scroll",r,{passive:!0});r();const c=[...document.querySelectorAll(".toc a")],l=new IntersectionObserver(e=>{e.forEach(t=>{t.isIntersecting&&c.forEach(o=>o.classList.toggle("is-active",o.getAttribute("href")===`#${t.target.id}`))})},{rootMargin:"-30% 0px -60% 0px"});document.querySelectorAll(".clause").forEach(e=>l.observe(e));
